(()=>{"use strict";"undefined"!=typeof Office&&Office.onReady(()=>{const{reason:e,confidenceLabel:n}=function(e){try{const n=new URLSearchParams(e).get("data");if(!n)return{reason:"",confidence:0,confidenceLabel:"0%"};const t=JSON.parse(n),c=null!=t.confidence?Number(t.confidence):0;return{reason:t.reason||"",confidence:c,confidenceLabel:`${Math.round(100*c)}%`}}catch{return{reason:"",confidence:0,confidenceLabel:"0%"}}}(window.location.search);document.getElementById("reason").textContent=e||"Sensitive content detected.",document.getElementById("confidence").textContent="0%"!==n?`Confidence: ${n}`:"",document.getElementById("btn-encrypt").addEventListener("click",()=>{Office.context.ui.messageParent("encrypt")}),document.getElementById("btn-send").addEventListener("click",()=>{Office.context.ui.messageParent("sendAnyway")}),document.getElementById("btn-cancel").addEventListener("click",()=>{Office.context.ui.messageParent("cancel")})})})();